"""KinDER standard-mode controller. Robot facts plus RGB-D and encoder feedback only."""
from pathlib import Path
import json, sys, time
import numpy as np
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
from rcb_client import Robot
OUT=Path('/app/output'); OUT.mkdir(exist_ok=True)
r=Robot(); spec=r.spec()
(OUT/'spec.json').write_text(json.dumps(spec,indent=2))
P=np.array(spec['arm']['position_m']); AX=np.array(spec['arm']['axis']); EE=np.array(spec['arm']['end_effector']['position_m'])

def fk(q,point=EE):
    R=np.eye(3); t=np.zeros(3)
    for p,a,theta in zip(P,AX,q):
        rr=Rotation.from_rotvec(a*theta).as_matrix()
        t=t+R@(p-rr@p); R=R@rr
    return R@point+t,R

def world(q,base,point=EE):
    p,R=fk(q,point); B=Rotation.from_rotvec([0,0,base[2]]).as_matrix()
    return B@p+np.r_[base[:2],0],B@R

def state(res):return np.array(res.meta['proprio']['now'],dtype=float)

def observe(name='latest'):
    res=r.get_obs(include_depth=True,video='none'); res.save(str(OUT/name)); return res

def send(A,name='move'):
    A=np.asarray(A,float).reshape(-1,11)
    with (OUT/'actions.jsonl').open('a') as f:f.write(json.dumps({'name':name,'actions':A.tolist()})+'\n')
    res=r.submit('delta',A,include_depth=True,video='none',note=name)
    res.save(str(OUT/name)); print(name,res.meta['control_steps'],res.meta['done'],res.meta['reason'],np.round(state(res)[[0,1,2,20]],4).tolist(),flush=True)
    return res

def move(q=None,base=None,grip=0,rate=.06,steps=100,name='move'):
    res=observe(); s=state(res)
    q=s[6:13] if q is None else np.array(q,float)
    base=s[:3] if base is None else np.array(base,float)
    for i in range(steps):
        s=state(res); dq=q-s[6:13]; db=base-s[:3]
        if np.max(np.abs(dq))<.008 and np.max(np.abs(db))<.006:break
        a=np.r_[np.clip(db,-rate,rate),np.clip(dq,-rate,rate),grip]
        if np.linalg.norm(a[:2])>rate:a[:2]*=rate/np.linalg.norm(a[:2])
        res=send(a,name)
        if res.done:break
    res.save(str(OUT/name)); return res

def ik(target,Rtarget,q0=None,base=None):
    s=state(observe())
    if q0 is None:q0=s[6:13]
    if base is not None:
        B=Rotation.from_rotvec([0,0,base[2]]).as_matrix()
        target=B.T@(np.array(target)-np.r_[base[:2],0]); Rtarget=B.T@Rtarget
    low=np.array([-100,-2.24,-100,-2.57,-100,-2.09,-100.]); high=-low
    def fun(q):
        p,R=fk(q)
        rot=Rotation.from_matrix(Rtarget@R.T).as_rotvec()
        return np.r_[(p-target)*5,rot,q*.0001]
    sol=least_squares(fun,q0,bounds=(low,high),max_nfev=500,ftol=1e-10,xtol=1e-10,gtol=1e-10)
    print('IK',sol.cost,'q',sol.x,'pose',fk(sol.x)[0]); return sol.x

def camera_pose(res,cam='robot_wrist'):
    s=state(res); c=spec['cameras'][cam]['pose']; p=np.array(c['position_m'])
    if cam=='robot_wrist':p,R=world(s[6:13],s[:3],p)
    else:
        R=Rotation.from_rotvec([0,0,s[2]]).as_matrix();p=R@p+np.r_[s[:2],0]
    return p,R@np.array(c['forward']),R@np.array(c['up']),R@np.array(c['right'])

def pixel_world(res,u,v,depth,cam='robot_wrist'):
    p,f,up,right=camera_pose(res,cam); fy=240/np.tan(np.deg2rad(spec['cameras'][cam]['fovy_deg'])/2)
    return p+depth*(f+(u-319.5)/fy*right-(v-239.5)/fy*up)

if __name__=='__main__':
    cmd=sys.argv[1] if len(sys.argv)>1 else 'obs'
    if cmd=='obs':
        res=observe(sys.argv[2] if len(sys.argv)>2 else 'latest'); print(json.dumps(res.meta)); print('EE',world(state(res)[6:13],state(res)[:3])); print('camera',camera_pose(res))
    elif cmd=='replay':
        for line in (OUT/'actions.jsonl').read_text().splitlines():
            item=json.loads(line); r.submit('delta',item['actions'],video='none',note=item['name'])
